script:
frappe.ui.form.on('Product', {
    refresh: function(frm) {
        // Check if current user has System Manager role
        const hasSystemManagerRole = frappe.user.has_role('System Manager');

        if (!hasSystemManagerRole) {
            // Hide assignments section only for non-System Managers
            $('.form-assignments').hide();

            // Make assign_to field read-only for non-System Managers
            frm.set_df_property('assign_to', 'read_only', 1);
        } else {
            // Ensure assignments are visible for System Managers
            $('.form-assignments').show();

            // Make assign_to field editable for System Managers
            frm.set_df_property('assign_to', 'read_only', 0);
        }
    }
});

